export const envelope = [112, 28, 20];

export default function build(api) {
  const [W, H, D] = api.size;
  const seatY = 6;

  // -------------------------------------------------------------------------
  // Palette resolution with robust fallbacks
  // -------------------------------------------------------------------------
  const stonePrimary = api.theme.stone.primary || "minecraft:stone_bricks";
  const stoneAccent = api.theme.stone.accent || "minecraft:cracked_stone_bricks";
  const stoneStairs = api.theme.stone.stairs || "minecraft:stone_brick_stairs";
  const stoneSlab = api.theme.stone.slab || "minecraft:stone_brick_slab";
  const stoneWall = api.theme.stone.wall || "minecraft:stone_brick_wall";

  const woodPlanks = api.theme.wood.planks || "minecraft:spruce_planks";
  const woodLog = api.theme.wood.log || "minecraft:spruce_log";
  const woodStripped = api.theme.wood.stripped || "minecraft:stripped_spruce_log";
  const woodStairs = api.theme.wood.stairs || "minecraft:spruce_stairs";
  const woodSlab = api.theme.wood.slab || "minecraft:spruce_slab";
  const woodFence = api.theme.wood.fence || "minecraft:spruce_fence";
  const woodTrapdoor = api.theme.wood.trapdoor || "minecraft:spruce_trapdoor";

  const groundPavement = api.theme.ground.pavement || "minecraft:cobblestone";
  const groundKerb = api.theme.ground.kerb || "minecraft:stone_bricks";
  const groundPlinth = api.theme.ground.plinth || "minecraft:deepslate_bricks";

  const roofStairs = api.theme.roof.stairs || "minecraft:dark_oak_stairs";
  const roofSlab = api.theme.roof.slab || "minecraft:dark_oak_slab";
  const roofSolid = api.theme.roof.solid || "minecraft:dark_oak_planks";

  const glassPane = "minecraft:glass_pane";
  const ironBars = "minecraft:iron_bars";

  // -------------------------------------------------------------------------
  // Helpers
  // -------------------------------------------------------------------------
  function set(x, y, z, block) {
    if (x >= 0 && x < W && y >= 0 && y < H && z >= 0 && z < D) {
      api.set(x, y, z, block);
    }
  }

  function st(base, facing, half = "bottom") {
    return `${base}[facing=${facing},half=${half}]`;
  }

  function log(base, axis = "y") {
    return `${base}[axis=${axis}]`;
  }

  function slab(base, type = "bottom") {
    return `${base}[type=${type}]`;
  }

  function fill(x1, y1, z1, x2, y2, z2, block) {
    const minX = Math.max(0, Math.min(x1, x2));
    const maxX = Math.min(W - 1, Math.max(x1, x2));
    const minY = Math.max(0, Math.min(y1, y2));
    const maxY = Math.min(H - 1, Math.max(y1, y2));
    const minZ = Math.max(0, Math.min(z1, z2));
    const maxZ = Math.min(D - 1, Math.max(z1, z2));

    for (let x = minX; x <= maxX; x++) {
      for (let y = minY; y <= maxY; y++) {
        for (let z = minZ; z <= maxZ; z++) {
          set(x, y, z, block);
        }
      }
    }
  }

  function randomStone() {
    const r = api.random();
    if (r < 0.65) return stonePrimary;
    if (r < 0.88) return stoneAccent;
    return groundPlinth;
  }

  function randomRoadPaver() {
    const r = api.random();
    if (r < 0.55) return groundPavement;
    if (r < 0.85) return stonePrimary;
    return stoneAccent;
  }

  function getGroundY(x, z) {
    const h = api.heightAt(x, z);
    return Math.max(0, Math.min(H - 1, seatY + h));
  }

  // -------------------------------------------------------------------------
  // Substructure: Piers, Abutments, and Pointed Cutwaters
  // -------------------------------------------------------------------------
  const pierIntervals = [
    { x1: 0, x2: 13, center: 6, isAbutment: true },
    { x1: 25, x2: 31, center: 28, isAbutment: false },
    { x1: 44, x2: 50, center: 47, isAbutment: false },
    { x1: 63, x2: 69, center: 66, isAbutment: false },
    { x1: 82, x2: 88, center: 85, isAbutment: false },
    { x1: 99, x2: 111, center: 105, isAbutment: true }
  ];

  for (const pier of pierIntervals) {
    const { x1, x2, center, isAbutment } = pier;

    // Main pier block (Z = 4..15)
    for (let x = x1; x <= x2; x++) {
      for (let z = 4; z <= 15; z++) {
        const gY = getGroundY(x, z);
        const topY = 7;
        for (let y = gY; y <= topY; y++) {
          set(x, y, z, y <= gY + 1 ? groundPlinth : randomStone());
        }
      }
    }

    // Cutwaters (Triangular pointed piers) on North & South for river piers
    if (!isAbutment) {
      // North Cutwater (Z = 0..3) pointing upstream/North
      const northOffsets = [
        { z: 3, dx: 2 },
        { z: 2, dx: 2 },
        { z: 1, dx: 1 },
        { z: 0, dx: 0 }
      ];
      for (const row of northOffsets) {
        for (let x = center - row.dx; x <= center + row.dx; x++) {
          const gY = getGroundY(x, row.z);
          for (let y = gY; y <= 7; y++) {
            set(x, y, row.z, y <= gY + 1 ? groundPlinth : randomStone());
          }
          // Paved refuge floor at Y = 8
          set(x, 8, row.z, groundPavement);
        }
      }

      // Parapet balustrades for North pedestrian refuge
      for (const row of northOffsets) {
        if (row.dx === 0) {
          set(center, 9, row.z, stoneWall);
        } else {
          set(center - row.dx, 9, row.z, stoneWall);
          set(center + row.dx, 9, row.z, stoneWall);
        }
      }

      // South Cutwater (Z = 16..19) pointing downstream/South
      const southOffsets = [
        { z: 16, dx: 2 },
        { z: 17, dx: 2 },
        { z: 18, dx: 1 },
        { z: 19, dx: 0 }
      ];
      for (const row of southOffsets) {
        for (let x = center - row.dx; x <= center + row.dx; x++) {
          const gY = getGroundY(x, row.z);
          for (let y = gY; y <= 7; y++) {
            set(x, y, row.z, y <= gY + 1 ? groundPlinth : randomStone());
          }
          // Paved refuge floor at Y = 8
          set(x, 8, row.z, groundPavement);
        }
      }

      // Parapet balustrades for South pedestrian refuge
      for (const row of southOffsets) {
        if (row.dx === 0) {
          set(center, 9, row.z, stoneWall);
        } else {
          set(center - row.dx, 9, row.z, stoneWall);
          set(center + row.dx, 9, row.z, stoneWall);
        }
      }
    }
  }

  // -------------------------------------------------------------------------
  // Massive Stone Arches & Spandrels
  // -------------------------------------------------------------------------
  const archSpans = [
    { xStart: 14, xEnd: 24 },
    { xStart: 32, xEnd: 43 },
    { xStart: 51, xEnd: 62 },
    { xStart: 70, xEnd: 81 },
    { xStart: 89, xEnd: 98 }
  ];

  for (const span of archSpans) {
    const { xStart, xEnd } = span;
    const midX = (xStart + xEnd) / 2;
    const radius = (xEnd - xStart + 1) / 2;
    const ySpring = 3.2;
    const yCrown = 7.0;

    for (let x = xStart; x <= xEnd; x++) {
      const u = (x - midX) / radius;
      const curve = yCrown - (yCrown - ySpring) * (u * u);
      const archY = Math.floor(curve);

      for (let z = 4; z <= 15; z++) {
        // Arch ring block
        if (archY >= 0 && archY <= 7) {
          if (x < midX) {
            set(x, archY, z, st(stoneStairs, "east", "top"));
          } else if (x > midX) {
            set(x, archY, z, st(stoneStairs, "west", "top"));
          } else {
            set(x, archY, z, slab(stoneSlab, "top"));
          }
        }

        // Solid masonry spandrel fill above arch ring up to deck level
        for (let y = archY + 1; y <= 7; y++) {
          set(x, y, z, randomStone());
        }
      }
    }
  }

  // -------------------------------------------------------------------------
  // Bridge Roadway & Sidewalk Deck (Y = 7..8)
  // -------------------------------------------------------------------------
  // Continuous stone deck base at Y = 7
  for (let x = 0; x < W; x++) {
    for (let z = 4; z <= 15; z++) {
      set(x, 7, z, randomStone());
    }
  }

  // Roadway paving and curbs at Y = 8
  for (let x = 0; x < W; x++) {
    // Curbs / gutters
    set(x, 8, 6, groundKerb);
    set(x, 8, 13, groundKerb);

    // Cobbled street
    for (let z = 7; z <= 12; z++) {
      set(x, 8, z, randomRoadPaver());
    }

    // Under-house base flooring at Y = 8
    for (let z = 0; z <= 5; z++) {
      set(x, 8, z, woodPlanks);
    }
    for (let z = 14; z < D; z++) {
      set(x, 8, z, woodPlanks);
    }
  }

  // Abutment retaining / approach fill for banks
  for (let x = 0; x <= 13; x++) {
    for (let z = 0; z < D; z++) {
      const gY = getGroundY(x, z);
      for (let y = gY; y <= 7; y++) {
        set(x, y, z, y <= gY + 1 ? groundPlinth : randomStone());
      }
    }
  }
  for (let x = 99; x < W; x++) {
    for (let z = 0; z < D; z++) {
      const gY = getGroundY(x, z);
      for (let y = gY; y <= 7; y++) {
        set(x, y, z, y <= gY + 1 ? groundPlinth : randomStone());
      }
    }
  }

  // -------------------------------------------------------------------------
  // Timber Under-Struts / Corbels Supporting Houses Over Water
  // -------------------------------------------------------------------------
  for (let x = 14; x <= 98; x += 3) {
    // North side overhang supports (Z = 0..3)
    set(x, 7, 1, log(woodLog, "z"));
    set(x, 7, 2, log(woodLog, "z"));
    set(x, 7, 3, log(woodLog, "z"));
    set(x, 6, 2, st(woodStairs, "south", "top"));
    set(x, 5, 3, st(woodStairs, "south", "top"));
    set(x, 6, 1, woodFence);

    // South side overhang supports (Z = 16..19)
    set(x, 7, 16, log(woodLog, "z"));
    set(x, 7, 17, log(woodLog, "z"));
    set(x, 7, 18, log(woodLog, "z"));
    set(x, 6, 17, st(woodStairs, "north", "top"));
    set(x, 5, 16, st(woodStairs, "north", "top"));
    set(x, 6, 18, woodFence);
  }

  // -------------------------------------------------------------------------
  // West Portal Gatehouse (X = 0..13)
  // -------------------------------------------------------------------------
  function buildWestGatehouse() {
    // Flanking solid towers and upper gatehall
    for (let x = 0; x <= 13; x++) {
      for (let z = 4; z <= 15; z++) {
        for (let y = 8; y <= 18; y++) {
          const isOuterWall =
            x === 0 || x === 13 || z === 4 || z === 15;
          const isRoadArch =
            z >= 7 && z <= 12 && y <= 13;

          if (isOuterWall) {
            set(x, y, z, randomStone());
          } else if (!isRoadArch) {
            if (y === 14) {
              set(x, y, z, stonePrimary); // Floor of upper guard hall
            } else if (y >= 15 && y <= 17) {
              // Interior of upper guard hall remains empty
            } else if (y === 18) {
              set(x, y, z, stonePrimary); // Roof of gatehouse
            } else if (y < 14) {
              // Side tower thick walls
              if (z <= 6 || z >= 13) {
                set(x, y, z, randomStone());
              }
            }
          }
        }
      }
    }

    // Portal arch ceiling decoration (vaulting)
    for (let x = 0; x <= 13; x++) {
      set(x, 13, 7, st(stoneStairs, "south", "top"));
      set(x, 13, 12, st(stoneStairs, "north", "top"));
      set(x, 14, 8, st(stoneStairs, "south", "top"));
      set(x, 14, 11, st(stoneStairs, "north", "top"));
      set(x, 14, 9, slab(stoneSlab, "top"));
      set(x, 14, 10, slab(stoneSlab, "top"));
    }

    // Portcullis grating at X = 3
    for (let z = 8; z <= 11; z++) {
      for (let y = 10; y <= 13; y++) {
        set(3, y, z, ironBars);
      }
    }

    // Machicolations and Parapets at Y = 19
    for (let x = 0; x <= 13; x++) {
      // Machicolation corbels
      set(x, 18, 3, st(stoneStairs, "north", "top"));
      set(x, 18, 16, st(stoneStairs, "south", "top"));

      // Crenellations
      const merlon = x % 2 === 0;
      set(x, 19, 3, merlon ? stonePrimary : stoneWall);
      set(x, 19, 16, merlon ? stonePrimary : stoneWall);
    }
    for (let z = 3; z <= 16; z++) {
      const merlon = z % 2 === 0;
      set(0, 19, z, merlon ? stonePrimary : stoneWall);
      set(13, 19, z, merlon ? stonePrimary : stoneWall);
    }

    // Corner Turrets rising to Y = 22
    const turrets = [
      { x: 0, z: 4 },
      { x: 0, z: 15 },
      { x: 13, z: 4 },
      { x: 13, z: 15 }
    ];
    for (const t of turrets) {
      for (let y = 19; y <= 22; y++) {
        set(t.x, y, t.z, stonePrimary);
      }
      set(t.x, 23, t.z, slab(stoneSlab, "bottom"));
    }
  }
  buildWestGatehouse();

  // -------------------------------------------------------------------------
  // East Portal Gatehouse & Watchtower (X = 98..111)
  // -------------------------------------------------------------------------
  function buildEastGatehouse() {
    for (let x = 98; x <= 111; x++) {
      for (let z = 4; z <= 15; z++) {
        for (let y = 8; y <= 18; y++) {
          const isOuterWall =
            x === 98 || x === 111 || z === 4 || z === 15;
          const isRoadArch =
            z >= 7 && z <= 12 && y <= 13;

          if (isOuterWall) {
            set(x, y, z, randomStone());
          } else if (!isRoadArch) {
            if (y === 14) {
              set(x, y, z, stonePrimary);
            } else if (y === 18) {
              set(x, y, z, stonePrimary);
            } else if (y < 14) {
              if (z <= 6 || z >= 13) {
                set(x, y, z, randomStone());
              }
            }
          }
        }
      }
    }

    // Portal vaulting
    for (let x = 98; x <= 111; x++) {
      set(x, 13, 7, st(stoneStairs, "south", "top"));
      set(x, 13, 12, st(stoneStairs, "north", "top"));
      set(x, 14, 8, st(stoneStairs, "south", "top"));
      set(x, 14, 11, st(stoneStairs, "north", "top"));
      set(x, 14, 9, slab(stoneSlab, "top"));
      set(x, 14, 10, slab(stoneSlab, "top"));
    }

    // Portcullis at X = 108
    for (let z = 8; z <= 11; z++) {
      for (let y = 10; y <= 13; y++) {
        set(108, y, z, ironBars);
      }
    }

    // Machicolations and parapets at Y = 19
    for (let x = 98; x <= 111; x++) {
      set(x, 18, 3, st(stoneStairs, "north", "top"));
      set(x, 18, 16, st(stoneStairs, "south", "top"));
      const merlon = x % 2 === 0;
      set(x, 19, 3, merlon ? stonePrimary : stoneWall);
      set(x, 19, 16, merlon ? stonePrimary : stoneWall);
    }
    for (let z = 3; z <= 16; z++) {
      const merlon = z % 2 === 0;
      set(98, 19, z, merlon ? stonePrimary : stoneWall);
      set(111, 19, z, merlon ? stonePrimary : stoneWall);
    }

    // High North-East Barbican Watchtower (X = 104..110, Z = 3..7) rising to Y = 25
    for (let x = 104; x <= 110; x++) {
      for (let z = 3; z <= 7; z++) {
        const isTowerWall =
          x === 104 || x === 110 || z === 3 || z === 7;
        for (let y = 19; y <= 24; y++) {
          if (isTowerWall) {
            set(x, y, z, randomStone());
          }
        }
        set(x, 24, z, stonePrimary); // Tower high roof floor
      }
    }
    // Conical / Hip roof over watchtower
    for (let x = 103; x <= 111; x++) {
      set(x, 25, 2, st(roofStairs, "south"));
      set(x, 25, 8, st(roofStairs, "north"));
    }
    for (let z = 2; z <= 8; z++) {
      set(103, 25, z, st(roofStairs, "east"));
      set(111, 25, z, st(roofStairs, "west"));
    }
    for (let x = 105; x <= 109; x++) {
      for (let z = 4; z <= 6; z++) {
        set(x, 26, z, roofSolid);
      }
    }
  }
  buildEastGatehouse();

  // -------------------------------------------------------------------------
  // Building Helpers for Timber-Framed Bridge Houses
  // -------------------------------------------------------------------------
  function buildNorthSouthGableRoof(x1, x2, z1, z2, yBase) {
    const midX = (x1 + x2) / 2;
    for (let x = x1; x <= x2; x++) {
      const dist = Math.abs(x - midX);
      const yStep = Math.floor((x2 - x1) / 2 - dist);
      const curY = yBase + yStep;

      for (let z = z1; z <= z2; z++) {
        if (x < midX - 0.5) {
          set(x, curY, z, st(roofStairs, "east"));
        } else if (x > midX + 0.5) {
          set(x, curY, z, st(roofStairs, "west"));
        } else {
          set(x, curY, z, roofSolid);
          set(x, curY + 1, z, slab(roofSlab, "bottom"));
        }
      }

      // Fill gable end walls
      for (let y = yBase; y < curY; y++) {
        set(x, y, z1, woodPlanks);
        set(x, y, z2, woodPlanks);
      }
    }
  }

  function buildEastWestRoof(x1, x2, z1, z2, yBase) {
    const midZ = (z1 + z2) / 2;
    for (let z = z1; z <= z2; z++) {
      const dist = Math.abs(z - midZ);
      const yStep = Math.floor((z2 - z1) / 2 - dist);
      const curY = yBase + yStep;

      for (let x = x1; x <= x2; x++) {
        if (z < midZ - 0.5) {
          set(x, curY, z, st(roofStairs, "south"));
        } else if (z > midZ + 0.5) {
          set(x, curY, z, st(roofStairs, "north"));
        } else {
          set(x, curY, z, roofSolid);
          set(x, curY + 1, z, slab(roofSlab, "bottom"));
        }
      }

      for (let y = yBase; y < curY; y++) {
        set(x1, y, z, woodPlanks);
        set(x2, y, z, woodPlanks);
      }
    }
  }

  function buildChimney(x, z, yBottom, yTop) {
    for (let y = yBottom; y <= yTop; y++) {
      set(x, y, z, randomStone());
    }
    set(x, yTop + 1, z, stoneWall);
  }

  // -------------------------------------------------------------------------
  // North Row Houses (Z = 0..5, X = 14..97)
  // -------------------------------------------------------------------------
  const northLots = [
    { x1: 14, x2: 22, type: "gable", peakY: 22 },
    { x1: 23, x2: 32, type: "refuge_lot", peakY: 21 },
    { x1: 33, x2: 42, type: "skybridge_lot", peakY: 22 },
    { x1: 43, x2: 51, type: "gable", peakY: 23 },
    { x1: 52, x2: 58, type: "observation_plaza", peakY: 9 },
    { x1: 59, x2: 68, type: "gable", peakY: 23 },
    { x1: 69, x2: 78, type: "skybridge_lot", peakY: 22 },
    { x1: 79, x2: 88, type: "refuge_lot", peakY: 21 },
    { x1: 89, x2: 97, type: "gable", peakY: 22 }
  ];

  for (const lot of northLots) {
    const { x1, x2, type } = lot;

    if (type === "observation_plaza") {
      // Mid-Bridge Open Observation Terrace
      for (let x = x1; x <= x2; x++) {
        for (let z = 0; z <= 5; z++) {
          set(x, 8, z, groundPavement);
          if (z === 0 || x === x1 || x === x2) {
            set(x, 9, z, stoneWall);
          }
        }
      }
      // Stone benches and central beacon
      set(x1 + 3, 9, 2, slab(stoneSlab, "top"));
      set(x1 + 3, 9, 3, slab(stoneSlab, "top"));
      set(x1 + 3, 10, 0, woodFence);
      set(x1 + 3, 11, 0, woodTrapdoor);
      continue;
    }

    // Standard Timber House
    const zGroundMin = 1;
    const zGroundMax = 5;
    const zJettyMin = 0; // Overhangs 1 block over water
    const zJettyMax = 5;

    // Ground floor structure (Y = 8..11)
    for (let x = x1; x <= x2; x++) {
      for (let z = zGroundMin; z <= zGroundMax; z++) {
        const isCorner =
          (x === x1 || x === x2) && (z === zGroundMin || z === zGroundMax);
        const isWall =
          x === x1 || x === x2 || z === zGroundMin || z === zGroundMax;

        if (isCorner) {
          for (let y = 8; y <= 11; y++) set(x, y, z, log(woodLog, "y"));
        } else if (isWall) {
          for (let y = 8; y <= 11; y++) {
            // Street front (Z = 5): Shop door & display window
            if (z === zGroundMax) {
              const midX = Math.floor((x1 + x2) / 2);
              if (x === midX) {
                // Open shop doorway
                if (y === 11) set(x, y, z, woodPlanks);
              } else if (x === midX - 1 || x === midX + 1) {
                if (y === 8) set(x, y, z, woodPlanks);
                else if (y === 9) set(x, y, z, woodPlanks); // Counter
                else if (y === 10) set(x, y, z, glassPane);
                else set(x, y, z, woodPlanks);
              } else {
                set(x, y, z, woodPlanks);
              }
            } else if (z === zGroundMin) {
              // Water-facing back wall
              if (y === 10 && (x === x1 + 2 || x === x2 - 2)) {
                set(x, y, z, glassPane);
              } else {
                set(x, y, z, woodPlanks);
              }
            } else {
              set(x, y, z, woodPlanks);
            }
          }
        }
      }
    }

    // Street awning at Y = 11 along shopfront
    for (let x = x1; x <= x2; x++) {
      set(x, 11, 6, st(woodStairs, "north"));
    }

    // 1st Floor (Y = 12..15): Jetty overhang
    for (let x = x1; x <= x2; x++) {
      for (let z = zJettyMin; z <= zJettyMax; z++) {
        // Floor at Y = 12
        set(x, 12, z, woodPlanks);

        const isCorner =
          (x === x1 || x === x2) && (z === zJettyMin || z === zJettyMax);
        const isWall =
          x === x1 || x === x2 || z === zJettyMin || z === zJettyMax;

        if (isCorner) {
          for (let y = 13; y <= 15; y++) set(x, y, z, log(woodLog, "y"));
        } else if (isWall) {
          for (let y = 13; y <= 15; y++) {
            if (y === 14 && (x % 3 === 0 || x === Math.floor((x1 + x2) / 2))) {
              set(x, y, z, glassPane);
            } else {
              set(x, y, z, woodPlanks);
            }
          }
        }
      }
    }

    // Overhang jetty support brackets at Y = 12, Z = 0
    for (let x = x1; x <= x2; x += 2) {
      set(x, 11, 0, st(woodStairs, "south", "top"));
    }

    // 2nd Floor / Ceiling at Y = 16
    for (let x = x1; x <= x2; x++) {
      for (let z = zJettyMin; z <= zJettyMax; z++) {
        set(x, 16, z, woodPlanks);
      }
    }

    // Roof construction
    if (type === "gable") {
      buildNorthSouthGableRoof(x1, x2, zJettyMin, zJettyMax, 17);
    } else {
      buildEastWestRoof(x1, x2, zJettyMin, zJettyMax, 17);
    }
  }

  // -------------------------------------------------------------------------
  // South Row Houses (Z = 14..19, X = 14..97)
  // -------------------------------------------------------------------------
  const southLots = [
    { x1: 14, x2: 23, type: "gable", peakY: 22 },
    { x1: 24, x2: 32, type: "refuge_lot", peakY: 21 },
    { x1: 33, x2: 42, type: "skybridge_lot", peakY: 22 },
    { x1: 43, x2: 51, type: "gable", peakY: 23 },
    { x1: 52, x2: 58, type: "bridge_chapel", peakY: 21 },
    { x1: 59, x2: 68, type: "gable", peakY: 23 },
    { x1: 69, x2: 78, type: "skybridge_lot", peakY: 22 },
    { x1: 79, x2: 87, type: "refuge_lot", peakY: 21 },
    { x1: 88, x2: 97, type: "gable", peakY: 23 }
  ];

  for (const lot of southLots) {
    const { x1, x2, type } = lot;

    if (type === "bridge_chapel") {
      // St. Nicholas Bridge Chapel (X = 52..58, Z = 14..19)
      for (let x = x1; x <= x2; x++) {
        for (let z = 14; z <= 19; z++) {
          for (let y = 8; y <= 16; y++) {
            const isWall = x === x1 || x === x2 || z === 14 || z === 19;
            if (isWall) {
              if (z === 14 && x === x1 + 3 && y <= 11) {
                // Chapel doorway
                if (y === 11) set(x, y, z, st(stoneStairs, "north", "top"));
              } else if (z === 19 && (x === x1 + 2 || x === x1 + 4) && y >= 11 && y <= 13) {
                set(x, y, z, glassPane); // Altar stained glass
              } else {
                set(x, y, z, randomStone());
              }
            }
          }
          set(x, 16, z, stonePrimary); // Vaulted ceiling
        }
      }
      // Chapel high gable roof
      buildNorthSouthGableRoof(x1, x2, 14, 19, 17);
      // Small stone bellcote turret with cross at peak
      set(x1 + 3, 21, 14, stoneWall);
      set(x1 + 3, 22, 14, stoneWall);
      set(x1 + 3, 23, 14, woodFence);
      continue;
    }

    const zGroundMin = 14;
    const zGroundMax = 18;
    const zJettyMin = 14;
    const zJettyMax = 19; // Overhangs 1 block over water

    // Ground floor (Y = 8..11)
    for (let x = x1; x <= x2; x++) {
      for (let z = zGroundMin; z <= zGroundMax; z++) {
        const isCorner =
          (x === x1 || x === x2) && (z === zGroundMin || z === zGroundMax);
        const isWall =
          x === x1 || x === x2 || z === zGroundMin || z === zGroundMax;

        if (isCorner) {
          for (let y = 8; y <= 11; y++) set(x, y, z, log(woodLog, "y"));
        } else if (isWall) {
          for (let y = 8; y <= 11; y++) {
            // Street front (Z = 14): Shop door & display
            if (z === zGroundMin) {
              const midX = Math.floor((x1 + x2) / 2);
              if (x === midX) {
                if (y === 11) set(x, y, z, woodPlanks);
              } else if (x === midX - 1 || x === midX + 1) {
                if (y === 8) set(x, y, z, woodPlanks);
                else if (y === 9) set(x, y, z, woodPlanks);
                else if (y === 10) set(x, y, z, glassPane);
                else set(x, y, z, woodPlanks);
              } else {
                set(x, y, z, woodPlanks);
              }
            } else if (z === zGroundMax) {
              if (y === 10 && (x === x1 + 2 || x === x2 - 2)) {
                set(x, y, z, glassPane);
              } else {
                set(x, y, z, woodPlanks);
              }
            } else {
              set(x, y, z, woodPlanks);
            }
          }
        }
      }
    }

    // Street awning at Y = 11 along shopfront
    for (let x = x1; x <= x2; x++) {
      set(x, 11, 13, st(woodStairs, "south"));
    }

    // 1st Floor (Y = 12..15): Jetty overhang
    for (let x = x1; x <= x2; x++) {
      for (let z = zJettyMin; z <= zJettyMax; z++) {
        set(x, 12, z, woodPlanks);

        const isCorner =
          (x === x1 || x === x2) && (z === zJettyMin || z === zJettyMax);
        const isWall =
          x === x1 || x === x2 || z === zJettyMin || z === zJettyMax;

        if (isCorner) {
          for (let y = 13; y <= 15; y++) set(x, y, z, log(woodLog, "y"));
        } else if (isWall) {
          for (let y = 13; y <= 15; y++) {
            if (y === 14 && (x % 3 === 0 || x === Math.floor((x1 + x2) / 2))) {
              set(x, y, z, glassPane);
            } else {
              set(x, y, z, woodPlanks);
            }
          }
        }
      }
    }

    // Overhang jetty support brackets at Y = 12, Z = 19
    for (let x = x1; x <= x2; x += 2) {
      set(x, 11, 19, st(woodStairs, "north", "top"));
    }

    // 2nd Floor / Ceiling at Y = 16
    for (let x = x1; x <= x2; x++) {
      for (let z = zJettyMin; z <= zJettyMax; z++) {
        set(x, 16, z, woodPlanks);
      }
    }

    // Roof
    if (type === "gable") {
      buildNorthSouthGableRoof(x1, x2, zJettyMin, zJettyMax, 17);
    } else {
      buildEastWestRoof(x1, x2, zJettyMin, zJettyMax, 17);
    }
  }

  // -------------------------------------------------------------------------
  // Overhead Timber Skybridges across the Central Roadway
  // -------------------------------------------------------------------------
  const skybridgeSpans = [
    { x1: 40, x2: 42 },
    { x1: 72, x2: 74 }
  ];

  for (const sb of skybridgeSpans) {
    const { x1, x2 } = sb;

    // Arch corbels under skybridge
    for (let x = x1; x <= x2; x++) {
      set(x, 11, 6, st(woodStairs, "south", "top"));
      set(x, 11, 13, st(woodStairs, "north", "top"));
    }

    // Walkable floor at Y = 12
    for (let x = x1; x <= x2; x++) {
      for (let z = 6; z <= 13; z++) {
        set(x, 12, z, woodPlanks);
      }
    }

    // Skybridge walls with viewing windows at Y = 13..15
    for (let z = 6; z <= 13; z++) {
      for (let y = 13; y <= 15; y++) {
        if (y === 14 && z >= 8 && z <= 11) {
          set(x1, y, z, glassPane);
          set(x2, y, z, glassPane);
        } else {
          set(x1, y, z, woodPlanks);
          set(x2, y, z, woodPlanks);
        }
      }
    }

    // Roof over skybridge at Y = 16..17
    for (let z = 5; z <= 14; z++) {
      set(x1 - 1, 16, z, st(roofStairs, "east"));
      set(x1, 17, z, st(roofStairs, "east"));
      set(x1 + 1, 17, z, roofSolid);
      set(x2, 17, z, st(roofStairs, "west"));
      set(x2 + 1, 16, z, st(roofStairs, "west"));
    }
  }

  // -------------------------------------------------------------------------
  // Authentic Stone Chimney Stacks Rising Above Roofs
  // -------------------------------------------------------------------------
  const chimneys = [
    { x: 19, z: 1, yBot: 12, yTop: 24 },
    { x: 36, z: 1, yBot: 12, yTop: 24 },
    { x: 64, z: 1, yBot: 12, yTop: 25 },
    { x: 84, z: 1, yBot: 12, yTop: 24 },
    { x: 19, z: 18, yBot: 12, yTop: 24 },
    { x: 48, z: 18, yBot: 12, yTop: 25 },
    { x: 64, z: 18, yBot: 12, yTop: 25 },
    { x: 92, z: 18, yBot: 12, yTop: 24 }
  ];

  for (const c of chimneys) {
    buildChimney(c.x, c.z, c.yBot, c.yTop);
  }

  // -------------------------------------------------------------------------
  // Return Structure Manifest, Anchors, and Interior Volumes
  // -------------------------------------------------------------------------
  const interiors = [
    // West Gatehouse Guard Hall
    { min: [3, 9, 7], max: [10, 13, 12], kind: "hall" },
    // East Gatehouse Barbican Hall
    { min: [101, 9, 7], max: [108, 13, 12], kind: "hall" },

    // North Inhabited Shops & Quarters
    { min: [15, 9, 1], max: [21, 11, 4], kind: "hall" },
    { min: [15, 13, 1], max: [21, 15, 4], kind: "quarters" },
    { min: [34, 9, 1], max: [41, 11, 4], kind: "hall" },
    { min: [34, 13, 1], max: [41, 15, 4], kind: "quarters" },
    { min: [44, 9, 1], max: [50, 11, 4], kind: "hall" },
    { min: [60, 9, 1], max: [67, 11, 4], kind: "hall" },
    { min: [80, 9, 1], max: [87, 11, 4], kind: "hall" },

    // South Inhabited Shops, Chapel & Quarters
    { min: [15, 9, 15], max: [22, 11, 18], kind: "hall" },
    { min: [15, 13, 15], max: [22, 15, 18], kind: "quarters" },
    { min: [53, 9, 15], max: [57, 13, 18], kind: "vault" }, // St. Nicholas Chapel
    { min: [60, 9, 15], max: [67, 11, 18], kind: "hall" },
    { min: [89, 9, 15], max: [96, 11, 18], kind: "hall" },

    // Overhead Covered Skybridges
    { min: [40, 13, 7], max: [42, 15, 12], kind: "bridge" },
    { min: [72, 13, 7], max: [74, 15, 12], kind: "bridge" }
  ];

  return {
    name: "inhabited_stone_bridge",
    seatY: seatY,
    anchors: {
      front: [56, 8, 0],
      west_portal: [0, 8, 9],
      east_portal: [111, 8, 9],
      chapel: [55, 8, 14]
    },
    interiors
  };
}
